"""Reproduce the development lookup tables using only Python's standard library."""
from pathlib import Path
import struct
ROOT = Path(__file__).resolve().parents[1]
forward = [0 if i < 4 else 2 ** ((min(i, 340) - 196) / 48) for i in range(344)]
(ROOT / 'modules/shift_gestures/forward_table.inc').write_text(
    '@ Generated by tools/generate_tables.py; IEEE float32 values.\n' +
    ''.join(f'    .word 0x{struct.unpack("<I", struct.pack("<f", x))[0]:08x}\n' for x in forward))
# Stretch only the lower half: 0.1 at CCW, 8 at center, 128 at CW.
# The upper half retains its previous positions and intervals.
intervals = [round(480000 * 80 ** (-i / 128)) if i < 128
             else round(96000 * 2 ** (-i / 32)) for i in range(257)]
(ROOT / 'modules/gene_shape/density_table.inc').write_text(
    '@ Generated by tools/generate_tables.py; sample intervals at 48 kHz.\n' +
    ''.join(f'    .word {interval}\n' for interval in intervals))
